cd /workspace/dev && python3 -c "
import sys; sys.path.insert(0,'/workspace/dev')
import gen, ref
stats={'cap':0,'mixed':0,'work':0,'pins':0,'tx':0,'acc':0,'rej':0,'stale':0,'inv':0}
for seed in range(600):
    r=gen.gen_request(seed)
    o=ref.run(r)
    if 'error' in o: stats['inv']+=1; continue
    for s in o['sessions']:
        for t in s['transactions']:
            stats['tx']+=1
            if t['violations'] is None: stats['stale']+=1; continue
            for i,k in enumerate(['cap','mixed','work','pins']):
                if t['violations'][i]>0: stats[k]+=1
            if t['accepted']: stats['acc']+=1
            else: stats['rej']+=1
print(stats)
"
